@@ -0,0 +1,48 @@
+// API keys, roles and the audit trail. A key has a `name` and a `role`:
+// `viewer` may only read, `cook` may also do kitchen work, `manager` may do
+// everything. Every request that changes data leaves an audit entry.
+import { AppError } from "../errors.js";
+
+/** The roles, from least to most allowed. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+// Routes ("METHOD /pattern") a cook may use besides reading.
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+// Reads only managers may see.
+const MANAGER_READS = new Set(["GET /audit"]);
+
+/** The API key record for a bearer token, or throws `unauthorized`. */
+export function authenticate(store, authorization) {
+  const m = /^Bearer\s+(\S+)\s*$/i.exec(String(authorization ?? ""));
+  const key = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1] && ROLES.includes(k.role));
+  if (!key) throw new AppError("unauthorized");
+  return key;
+}
+
+/** Throws `forbidden` unless `role` may use the route `METHOD /pattern`. */
+export function authorize(role, route) {
+  if (role === "manager") return;
+  if (MANAGER_READS.has(route)) throw new AppError("forbidden");
+  if (route.startsWith("GET ")) return;
+  if (role === "cook" && COOK_ROUTES.has(route)) return;
+  throw new AppError("forbidden");
+}
+
+/** Appends an audit entry { id, at, key, method, path, status }. */
+export function recordAudit(store, { key, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, key, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.id - a.id);
+}
