+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, auth } from "./helpers.js";
+
+test("requests without a key or with an unknown key are 401", async () => {
+  const { handle } = app();
+  const none = await handle({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const bad = await handle({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(bad.status, 401);
+  assert.equal(bad.body.error.code, "unauthorized");
+});
+
+test("viewers may only read", async () => {
+  const { handle, store } = app();
+  assert.equal((await handle({ path: "/items", headers: auth("viewer") })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: auth("viewer"), body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("cooks may cook, waste, log temperatures and count, but not more", async () => {
+  const { handle } = app();
+  const cook = auth("cook");
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: cook, body: { qty: 1, reason: "spilled" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: cook, body: { location: "dry" } })).status, 403);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: auth(), body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: cook, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: cook })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders", headers: cook, body: {} })).status, 403);
+  assert.equal((await handle({ path: "/audit", headers: cook })).status, 403);
+});
+
+test("changing requests are audited, newest first, for managers only", async () => {
+  const { handle } = app();
+  await handle({ method: "POST", path: "/recipes/1/cook", headers: auth("cook"), body: { portions: 1 } });
+  await handle({ method: "POST", path: "/orders/1/send", headers: auth("viewer") });
+  await handle({ path: "/items", headers: auth("viewer") });
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  const res = await handle({ path: "/audit", headers: auth() });
+  assert.equal(res.status, 200);
+  assert.deepEqual(res.body.map((e) => [e.key, e.method, e.path, e.status]), [
+    ["front desk", "POST", "/orders/1/send", 403],
+    ["line cook", "POST", "/recipes/1/cook", 200],
+  ]);
+  assert.equal(res.body[0].at, "2026-10-28T10:00:00.000Z");
+  assert.equal((await handle({ path: "/audit", headers: auth("viewer") })).status, 403);
+});
